// PastaSigil — line-art SVG marks, drawn like 19th-century botanical plates.
//
// Ported from pasta-sigils.jsx. Stroke only, no fills. Color is controlled
// by the `color` prop (default: ink).
//
// Behavior change from prototype: unknown shapes return null instead of
// silently falling back to Trofie. The prototype's behavior caused identical
// sigils to render for distinct shapes (cacio-pepe and bucatini both showed
// the same rod). Null lets the caller make a real decision.
//
// Usage:
//   <PastaSigil shape="trofie" size={70} />
//   <PastaSigil shape={recipe.shape_id} size={36} color={colors.ink70} />
//
// shape: case-insensitive, trimmed. Both "Trofie" and "trofie" work.

import React from 'react';
import Svg, { G, Path, Ellipse, Rect } from 'react-native-svg';
import { colors } from '@/constants/theme';

interface SigilProps {
  shape: string;
  size?: number;
  color?: string;
}

const STROKE_W = 1.6;
const HAIR_W = 0.9;
const HAIR_OPACITY = 0.55;

const SP = ({ d, color }: { d: string; color: string }) => (
  <Path
    d={d}
    fill="none"
    stroke={color}
    strokeWidth={STROKE_W}
    strokeLinecap="round"
    strokeLinejoin="round"
  />
);

const HP = ({ d, color }: { d: string; color: string }) => (
  <Path
    d={d}
    fill="none"
    stroke={color}
    strokeWidth={HAIR_W}
    strokeOpacity={HAIR_OPACITY}
    strokeLinecap="round"
    strokeLinejoin="round"
  />
);

