export const SUPPORTED_SIGILS = Object.keys(SIGILS);

export function PastaSigil({ shape, size = 60, color = colors.ink }: SigilProps) {
  const key = String(shape || '').toLowerCase().trim();
  const sigil = SIGILS[key];
  if (!sigil) return null;

  const h = Math.round(size * (320 / 240));
  return (
    <Svg width={size} height={h} viewBox="0 0 240 320">
      {sigil(color)}
    </Svg>
  );
}
